{"path":"services.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Offerings — {{BUSINESS_NAME}}</title>
  <meta name="description" content="Events and sessions that may support calm and clarity through scent-led practices.">
  <style>
    :root{
      --bg:#fbfbf8;--card:#ffffff;--muted:#6b6b6b;--accent:#6a8f6a;--accent-2:#6a6f8f;
      --maxw:980px;--radius:12px;--glass:rgba(255,255,255,0.6);
    }
    html,body{height:100%;background:linear-gradient(180deg,var(--bg),#f3f6f3);font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial;line-height:1.4;color:#222;margin:0}
    header{backdrop-filter:blur(6px);position:sticky;top:0;z-index:40;background:linear-gradient(180deg,rgba(255,255,255,0.6),rgba(255,255,255,0.3));border-bottom:1px solid rgba(0,0,0,0.04)}
    .navwrap{max-width:var(--maxw);margin:0 auto;display:flex;align-items:center;gap:18px;padding:14px}
    .brand{font-weight:700;color:var(--accent);letter-spacing:0.6px}
    nav{margin-left:auto}
    nav a{color:#2b2b2b;text-decoration:none;margin-left:16px;font-weight:600}
    .container{max-width:var(--maxw);margin:36px auto;padding:0 20px}
    .hero{display:grid;grid-template-columns:1fr 340px;gap:28px;align-items:center}
    .hero-card{background:var(--card);padding:28px;border-radius:var(--radius);box-shadow:0 6px 22px rgba(15,15,15,0.06)}
    h1{margin:0 0 6px 0;font-size:26px}
    .tagline{color:var(--muted);margin-bottom:18px}
    .hero-cta{display:flex;gap:10px}
    .btn{background:var(--accent);color:#fff;padding:10px 14px;border-radius:10px;border:0;cursor:pointer;font-weight:700}
    .btn.secondary{background:transparent;color:var(--accent-2);border:1px solid rgba(100,100,130,0.12)}
    .services{margin-top:22px;display:grid;gap:14px}
    .service{padding:16px;border-radius:12px;background:linear-gradient(180deg,var(--glass),rgba(255,255,255,0.85));border:1px solid rgba(0,0,0,0.03)}
    .svc-head{display:flex;justify-content:space-between;align-items:center}
    .price{font-weight:800;color:var(--accent-2)}
    .muted{color:var(--muted);font-size:14px}

    section.reveal{opacity:0;transform:translateY(12px);transition:opacity 420ms ease,transform 420ms ease}
    section.reveal.visible{opacity:1;transform:none}

    .pillars{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:20px}
    .pillar{background:var(--card);padding:16px;border-radius:12px}
    .case-notes{margin-top:30px}
    .case{background:linear-gradient(180deg,#fff,#fbfbff);padding:16px;border-radius:12px;margin-bottom:12px}
    .faq{margin-top:20px}
    details{background:var(--card);padding:12px;border-radius:10px;margin-bottom:8px}

    footer{max-width:var(--maxw);margin:36px auto;padding:20px;text-align:center;color:var(--muted)}

    /* modal */
    .modal-backdrop{position:fixed;inset:0;background:rgba(18,18,18,0.45);display:none;align-items:center;justify-content:center;z-index:80}
    .modal{background:#fff;width:min(720px,92%);border-radius:14px;padding:20px;box-shadow:0 20px 50px rgba(10,10,10,0.25)}
    .modal .steps{display:flex;gap:10px;align-items:center}
    .breath-visual{height:86px;border-radius:10px;background:linear-gradient(90deg,var(--accent-2),var(--accent));display:flex;align-items:center;justify-content:center;color:#fff;font-weight:700}
    .close{border:0;background:transparent;font-size:18px;cursor:pointer}

    @media (max-width:880px){.hero{grid-template-columns:1fr;}.pillars{grid-template-columns:1fr}.brand{font-size:14px}}
  </style>
</head>
<body>
  <header>
    <div class="navwrap">
      <div class="brand">{{BUSINESS_NAME}}</div>
      <nav>
        <a href="index.html">Gather</a>
        <a href="services.html">Offerings</a>
        <a href="blends.html">Scent Lab</a>
        <a href="shop.html">Apothecary</a>
        <a href="pricing.html">Investment</a>
        <a href="book.html">Reserve</a>
        <a href="contact.html">Connect</a>
      </nav>
    </div>
  </header>

  <main class="container">
    <section class="hero reveal" id="hero">
      <div class="hero-card">
        <h1>Programs and sessions that may support focus and ease</h1>
        <p class="tagline">Small-group gatherings, guided practice sessions, and bespoke scent consultations—built for people who want simple, repeatable rituals.</p>
        <div class="hero-cta">
          <button class="btn" id="open-exercise">Try a short guided moment</button>
          <a class="btn secondary" href="book.html">{{PRIMARY_CTA_LABEL}}</a>
        </div>
        <div class="services">
          <div class="service">
            <div class="svc-head"><strong>Seasonal Series — Circle</strong><span class="price">From $45 / session</span></div>
            <p class="muted">A four-week cohort that cycles through simple practices, scent introductions, and shared intention-setting. Pricing shown per session; sliding-scale seats available.</p>
          </div>
          <div class="service">
            <div class="svc-head"><strong>Private Practice Session</strong><span class="price">$120</span></div>
            <p class="muted">One-on-one time for a custom plan: aromatic profile, safe dilution guidance, and a short at-home ritual to try between meetings.</p>
          </div>
          <div class="service">
            <div class="svc-head"><strong>Scent Lab Workshop</strong><span class="price">$30–$80</span></div>
            <p class="muted">Hands-on mixing, aroma safety basics, and a take-home sample. Perfect for groups, workplaces, or as an introduction to blending.</p>
          </div>
        </div>
      </div>

      <aside class="hero-card">
        <h3>Quick details</h3>
        <p class="muted">Sessions run in person in {{CITY}}, {{STATE}}, and virtually. Bookings open year-round. Use {{PHONE}} or {{EMAIL}} for group requests.</p>
        <div style="margin-top:14px">
          <button class="btn" onclick="location.href='book.html'">Reserve a slot</button>
        </div>
      </aside>
    </section>

    <section class="myth_vs_truth reveal" id="myths">
      <h2>Clarifying common ideas</h2>
      <div class="pillars">
        <div class="pillar">
          <h4>Myth</h4>
          <p class="muted">Essential oils cure illness.</p>
          <h4>Real note</h4>
          <p>Careful scent work is supportive and experiential—designed to frame attention and mood, not replace medical care.</p>
        </div>
        <div class="pillar">
          <h4>Myth</h4>
          <p class="muted">Natural equals always safe.</p>
          <h4>Real note</h4>
          <p>Plants are potent. Dilution, patch tests, and awareness of pregnancy or pets are part of any responsible plan.</p>
        </div>
        <div class="pillar">
          <h4>Myth</h4>
          <p class="muted">Everyone responds the same way.</p>
          <h4>Real note</h4>
          <p>Individual differences matter. Sessions aim to provide options and choices so you can find what resonates.</p>
        </div>
      </div>
    </section>

    <section class="pillars reveal" id="pillars">
      <h2>How the programs are structured</h2>
      <div style="display:grid;gap:12px;">
        <div class="service">
          <strong>Anchor Minutes</strong>
          <p class="muted">Short practices for daily recalibration—breath + scent pairings to practice alone.</p>
        </div>
        <div class="service">
          <strong>Learning Labs</strong>
          <p class="muted">Practical sessions focused on making blends, safe application, and at-home rituals that may support sleep or focus.</p>
        </div>
        <div class="service">
          <strong>Guided Circles</strong>
          <p class="muted">Shared sessions with a gentle structure: scent exploration, a short guided practice, and group reflection.</p>
        </div>
      </div>
    </section>

    <section class="case_notes reveal" id="case-notes">
      <h2>Notes from recent meetings</h2>
      <div class="case">
        <strong>Office pop-up — October</strong>
        <p class="muted">A lunchtime lab where a small team learned two blends and practiced a three-breath reset. Feedback: clear steps helped make a habit.</p>
      </div>
      <div class="case">
        <strong>Weekend Circle — January</strong>
        <p class="muted">A mixed-age group practiced journaling prompts paired with scent. Most participants shared a simple at-home version to try for a week.</p>
      </div>
    </section>

    <section class="faq reveal" id="faq">
      <h2>Frequently asked practical questions</h2>
      <details>
        <summary>Are these medical therapies?</summary>
        <p class="muted">No. Sessions are experience-based and educational. They may support wellbeing but are not a substitute for medical treatment.</p>
      </details>
      <details>
        <summary>How should I dilute oils and test for sensitivity?</summary>
        <p class="muted">Safe dilution is covered in every workshop. A common home guideline is 1–3% in a carrier for topical use; always do a patch test and reduce concentration for children, pregnancy, or if you have skin concerns.</p>
      </details>
      <details>
        <summary>What about pets and pregnancy?</summary>
        <p class="muted">Some aromatics are not appropriate for pregnancy or for pets. If pregnant or caring for animals, share that up front so we can suggest safe alternatives.</p>
      </details>
      <details>
        <summary>Do you offer group or workplace visits?</summary>
        <p class="muted">Yes—group workshops and pop-ups can be arranged. Email {{EMAIL}} to discuss availability and group pricing.</p>
      </details>
    </section>

    <section class="cta reveal" id="cta">
      <div style="display:flex;gap:12px;align-items:center;justify-content:space-between;background:var(--card);padding:18px;border-radius:14px;margin-top:20px">
        <div>
          <h3 style="margin:0">Ready to make a small shift?</h3>
          <p class="muted" style="margin:6px 0">Book a trial session or join the next small cohort.</p>
        </div>
        <div style="display:flex;gap:8px">
          <a class="btn" href="book.html">{{PRIMARY_CTA_LABEL}}</a>
          <button class="btn secondary" id="open-exercise-2">Try a 3-minute pause</button>
        </div>
      </div>
    </section>

  </main>

  <div class="modal-backdrop" id="exercise-modal" role="dialog" aria-modal="true" aria-hidden="true">
    <div class="modal" role="document">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px">
        <strong>Try a short guided moment</strong>
        <button class="close" id="close-modal">×</button>
      </div>
      <div>
        <p class="muted">Choose what feels right: a breathing rhythm, a short journal prompt, or an intention-setting practice.</p>
        <div style="margin-top:12px;display:flex;gap:8px;">
          <button class="btn" data-mode="breath">Breathing</button>
          <button class="btn secondary" data-mode="journal">Journaling</button>
          <button class="btn secondary" data-mode="intention">Intention</button>
        </div>
        <div id="exercise-area" style="margin-top:14px"></div>
      </div>
    </div>
  </div>

  <footer>
    <div>{{BUSINESS_NAME}} — {{TAGLINE}} · <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> · <a href="tel:{{PHONE}}">{{PHONE}}</a></div>
  </footer>

  <script>
    // Scroll reveal with reduced-motion support
    (function(){
      const prefersReduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const els = document.querySelectorAll('.reveal');
      if(prefersReduced){ els.forEach(e=>e.classList.add('visible')); return; }
      const obs = new IntersectionObserver((entries)=>{
        entries.forEach(entry=>{
          if(entry.isIntersecting){ entry.target.classList.add('visible'); obs.unobserve(entry.target); }
        });
      },{threshold:0.09});
      els.forEach(e=>obs.observe(e));
    })();

    // Modal guided exercise
    (function(){
      const modal = document.getElementById('exercise-modal');
      const openBtns = [document.getElementById('open-exercise'),document.getElementById('open-exercise-2')];
      const closeBtn = document.getElementById('close-modal');
      const area = document.getElementById('exercise-area');

      openBtns.forEach(b=>b && b.addEventListener('click',open));
      closeBtn.addEventListener('click',close);
      modal.addEventListener('click',(e)=>{ if(e.target===modal) close(); });

      function open(){ modal.style.display='flex'; modal.setAttribute('aria-hidden','false'); }
      function close(){ modal.style.display='none'; modal.setAttribute('aria-hidden','true'); stopBreath(); }

      // Mode buttons
      document.querySelectorAll('[data-mode]').forEach(btn=>btn.addEventListener('click',()=>{
        startMode(btn.getAttribute('data-mode'));
      }));

      // Breathing visual
      let breathTimer;
      function startMode(mode){ stopBreath(); area.innerHTML='';
        if(mode==='breath'){
          const el = document.createElement('div'); el.className='breath-visual'; el.textContent='Begin'; area.appendChild(el);
          let phase=0; const texts=['Breathe in','Hold','Breathe out']; el.textContent=texts[phase];
          breathTimer=setInterval(()=>{ phase=(phase+1)%3; el.textContent=texts[phase]; },3500);
        } else if(mode==='journal'){
          area.innerHTML='<label class="muted">Prompt:</label><div style="margin:8px 0;background:#f7f7fb;padding:10px;border-radius:8px">Write for 3 minutes: What small change do I want to try this week?</div><textarea style="width:100%;height:90px;border-radius:8px;padding:8px;border:1px solid #e6e6e6"></textarea>';
        } else if(mode==='intention'){
          area.innerHTML='<div class="muted">Choose a short intention and repeat it silently for one minute.</div><div style="margin-top:8px"><button class="btn" onclick="(function(){alert(\'Try repeating: I am steady. I return to breath.\');})();">Show an intention</button></div>';
        }
      }
      function stopBreath(){ clearInterval(breathTimer); breathTimer=null; }
    })();
  </script>
</body>
</html>"} 
