<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Apothecary — Products</title>
  <meta name="description" content="Small-batch blends and starter kits. Safety notes included.">
  <style>
    :root{--bg:#fbfffd;--card:#fff;--accent:#6a7a6a;--muted:#5f5f5f;--maxw:980px}
    html,body{font-family:Inter,system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial;margin:0;background:var(--bg);color:#222}
    header{position:sticky;top:0;background:rgba(255,255,255,0.8);backdrop-filter:blur(3px);border-bottom:1px solid rgba(0,0,0,0.04)}
    .navwrap{max-width:var(--maxw);margin:0 auto;padding:12px;display:flex;align-items:center}
    .brand{font-weight:800;color:var(--accent)}
    nav{margin-left:auto}
    nav a{margin-left:16px;text-decoration:none;color:#333;font-weight:600}
