<body>
  <header>
    <div class="navwrap">
      <div class="brand">{{BUSINESS_NAME}}</div>
      <nav>
        <a href="index.html">Home</a>
        <a href="services.html">Offerings</a>
        <a href="blends.html">Scent Lab</a>
        <a href="shop.html">Apothecary</a>
        <a href="contact.html">Connect</a>
      </nav>
    </div>
  </header>

  <main class="container">
    <h1>Apothecary</h1>
    <p class="muted">Small-batch blends, starter kits, and single oils. Safety notes are included with each product. No medical claims—products are for sensory use and may support everyday rituals.</p>

    <section class="grid" id="catalog">
      <div class="item" data-id="kit-1">
        <strong>Starter Kit — The Home Set</strong>
        <div class="muted">3 sample blends, dilution card, and a small inhaler. Good for someone new to mixing.</div>
        <div class="price">$28</div>
        <div class="actions"><button class="add btn">Add</button><button class="btn secondary" onclick="location.href='book.html'">Questions?</button></div>
      </div>

      <div class="item" data-id="roll-1">
        <strong>Evening Roll — 10ml</strong>
        <div class="muted">Pre-diluted 3% roll-on for topical use. Patch test before use; not for pregnancy without review.</div>
        <div class="price">$18</div>
        <div class="actions"><button class="add btn">Add</button><button class="btn secondary" onclick="alert('All products ship from the small-batch studio.');">Details</button></div>
